-- v20 HS codes: every FBR HS Code and Custom HS Code from Sale_Sheet_Ammendment_13-09-2026.xlsx.
-- FBR codes: 7805 rows from 'FBR Codes Sheet'. Custom codes: 8603 rows from 'Customs HS Code'.
-- Custom descriptions keep the sheet text exactly, joined with every extra description row listed under the code.
-- Existing codes keep their id, prices and links; only the description is refreshed. Missing codes are added.
-- Run after upgrade-v20.sql. Rerunning is safe.
DROP TABLE IF EXISTS ba_v20_fbr_stage;
DROP TABLE IF EXISTS ba_v20_custom_stage;
CREATE TABLE ba_v20_fbr_stage AS SELECT serial_number, hs_code, description FROM fbr_hs_codes WHERE 1=0;
CREATE TABLE ba_v20_custom_stage AS SELECT serial_number, hs_code, description FROM custom_hs_codes WHERE 1=0;
UPDATE fbr_hs_codes t JOIN ba_v20_fbr_stage s ON t.hs_code=s.hs_code AND t.deleted_at IS NULL SET t.description=s.description;
UPDATE custom_hs_codes t JOIN ba_v20_custom_stage s ON t.hs_code=s.hs_code AND t.deleted_at IS NULL SET t.description=s.description;
SELECT 'FBR HS codes from sheet' AS check_item, COUNT(*) AS sheet_rows, (SELECT COUNT(DISTINCT f.hs_code) FROM fbr_hs_codes f JOIN ba_v20_fbr_stage s ON s.hs_code=f.hs_code AND f.description=s.description AND f.deleted_at IS NULL) AS in_database FROM ba_v20_fbr_stage UNION ALL SELECT 'Custom HS codes from sheet', COUNT(*), (SELECT COUNT(DISTINCT c.hs_code) FROM custom_hs_codes c JOIN ba_v20_custom_stage s ON s.hs_code=c.hs_code AND c.description=s.description AND c.deleted_at IS NULL) FROM ba_v20_custom_stage;
DROP TABLE ba_v20_fbr_stage;
DROP TABLE ba_v20_custom_stage;
