INSERT INTO fbr_hs_codes(id,serial_number,hs_code,description,verification) SELECT UUID(),s.serial_number,s.hs_code,s.description,'verified' FROM ba_v20_fbr_stage s WHERE NOT EXISTS (SELECT 1 FROM fbr_hs_codes t WHERE t.hs_code=s.hs_code AND t.deleted_at IS NULL);
INSERT INTO custom_hs_codes(id,serial_number,hs_code,description,verification) SELECT UUID(),s.serial_number,s.hs_code,s.description,'verified' FROM ba_v20_custom_stage s WHERE NOT EXISTS (SELECT 1 FROM custom_hs_codes t WHERE t.hs_code=s.hs_code AND t.deleted_at IS NULL);
